mapper.select:
SELECT l.LOG_NO AS logNo, t.TITLE AS title, t.STATUS AS status, t.START_DATE AS startDate, t.END_DATE AS endDate,
req.USER_NAME AS requesterName, req.EMAIL AS requesterEmail,
mgr_u.USER_NAME AS assigneeName, mgr_u.EMAIL AS assigneeEmail FROM TODOLOG l LEFT JOIN TODO t ON l.TODO_NO = t.TODO_NO LEFT JOIN USERS req ON t.USER_NO = req.USER_NO LEFT JOIN REPRESENTATIVE r ON l.REPRESENTATIVE_NO = r.REPRESENTATIVE_NO LEFT JOIN USERS mgr_u ON r.REPRESENTATIVE_NO = mgr_u.USER_NO WHERE l.LOG_NO = #{logNo} AND req.COMPANY_NO = #{companyNo}
